#!/bin/bash
sed -i '/suspend fun resetSkipCount/i \    suspend fun addNextActionToProject(projectId: String, actionText: String, contextId: String?) {\n        val item = Item(\n            rawText = actionText,\n            actionText = actionText,\n            status = Status.NEXT_ACTION,\n            projectId = projectId,\n            contextId = contextId,\n            source = Source.IN_APP\n        )\n        val event = Event(\n            itemId = item.id,\n            fromStatus = null,\n            toStatus = Status.NEXT_ACTION\n        )\n        db.withTransaction {\n            dao.insertItem(item)\n            dao.insertEvent(event)\n        }\n    }\n' app/src/main/java/com/adarsh/sift/data/ItemRepository.kt
